def tirage(n, hmax=4, valeurs=None):
    """Arbre aléatoire de n noeuds et de hauteur au plus hmax (triplets)."""
    vals = list(valeurs) if valeurs else sample(range(1, 30), n)
    def gen(n, h):
        if n == 0:
            return None
        cap = 2 ** (h - 1) - 1
        k = randint(max(0, n - 1 - cap), min(n - 1, cap))
        return (vals.pop(), gen(k, h - 1), gen(n - 1 - k, h - 1))
    return gen(n, hmax)

