    W = 4 * 2 ** (H - 1)
    lignes = []
    niveau = [(t, 0)]
    for prof in range(H):
        ligne = [" "] * (W + 4)
        liens = [" "] * (W + 4)
        suivant = []
        for noeud, k in niveau:
